import{_ as t,o as r,c as n,ah as a}from"./chunks/framework.C-FRNfAJ.js";const m=JSON.parse('{"title":"Generated documents","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"en/guide/documents.md","filePath":"src/en/guide/documents.md"}'),d={name:"en/guide/documents.md"};function o(i,e,s,c,h,l){return r(),n("div",null,[...e[0]||(e[0]=[a('<h1 id="generated-documents" tabindex="-1">Generated documents <a class="header-anchor" href="#generated-documents" aria-label="Permalink to &quot;Generated documents&quot;">​</a></h1><p>Module 32 brings together all documents produced by Kura. There is no <code>generated_document</code> table: each document is read <strong>where it is stored</strong>, in its business table, and “My documents” lists them for an account.</p><h2 id="catalogue" tabindex="-1">Catalogue <a class="header-anchor" href="#catalogue" aria-label="Permalink to &quot;Catalogue&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Document</th><th>Reference</th><th>Generated when</th><th>Signatories</th></tr></thead><tbody><tr><td>Training agreement</td><td><code>CONV-NB-YYYY-XXX</code></td><td>edPage countersignature</td><td>Learner (or legal representative), edPage</td></tr><tr><td>Tripartite agreement</td><td><code>CONVT-NB-YYYY-XXX</code></td><td>After the agreement, if a funder is designated</td><td>Learner, funder, edPage</td></tr><tr><td>Internship agreement</td><td><code>CONVS-NB-YYYY-XXX</code></td><td>On sending by the Coordinator</td><td>Learner (or legal representative), company, edPage</td></tr><tr><td>Welcome booklet</td><td><code>LA-NB-YYYY-XXX</code></td><td>Full payment of the 1st instalment</td><td>No signature</td></tr><tr><td>Invoice</td><td><code>FAC-NB-YYYY-XXX</code></td><td>Instalment issue</td><td>—</td></tr><tr><td>Credit note</td><td><code>AV-NB-YYYY-XXX</code></td><td>Cancellation or refund</td><td>—</td></tr><tr><td>Certificate</td><td><code>CERT-NB-YYYY-XXX</code></td><td>Delivery by the Coordinator</td><td>Jury president</td></tr><tr><td>Partial attestation</td><td><code>ATP-NB-YYYY-XXX</code></td><td>Withdrawal with at least one validated block</td><td>Coordinator</td></tr><tr><td>Transcript of competences</td><td><code>REL-NB-YYYY-XXX</code></td><td>With the certificate or attestation</td><td>Coordinator</td></tr><tr><td>Decision letter</td><td>—</td><td>Decision made</td><td>—</td></tr><tr><td>Cohort calendar</td><td>—</td><td>On demand</td><td>—</td></tr><tr><td>Activity report</td><td>—</td><td>On demand</td><td>—</td></tr><tr><td>Defence report</td><td><code>PVS-NB-YYYY-XXX</code></td><td>Jury decisions confirmed</td><td>Jury</td></tr></tbody></table><p>Every PDF is generated server-side with <code>barryvdh/laravel-dompdf</code>, stored on a <strong>private</strong> disk and protected by a SHA-256 fingerprint. An issued invoice or certificate is not reissued: it is corrected by a credit note or a replacement.</p><h2 id="agreements" tabindex="-1">Agreements <a class="header-anchor" href="#agreements" aria-label="Permalink to &quot;Agreements&quot;">​</a></h2><h3 id="training-agreement" tabindex="-1">Training agreement <a class="header-anchor" href="#training-agreement" aria-label="Permalink to &quot;Training agreement&quot;">​</a></h3><p>The Coordinator publishes the general terms as <strong>immutable versions</strong>. A new version only applies to subsequent signatures; every signed agreement keeps its own. Without a published text, no signature is possible.</p><p>Kura adds the specific terms: parties, programme, cohort, format, price excluding tax and the 30/40/30 schedule on the cohort dates. Signature opens when the file is complete (cohort, consents).</p><h3 id="tripartite-agreement" tabindex="-1">Tripartite agreement <a class="header-anchor" href="#tripartite-agreement" aria-label="Permalink to &quot;Tripartite agreement&quot;">​</a></h3><p>Prepared on countersignature of a training agreement with a funder, whose terms it repeats. The funder signs it by code from “Funded learners”; edPage countersigns according to the Administrator&#39;s setting. It blocks neither the enrolment nor the billing.</p><h3 id="internship-agreement" tabindex="-1">Internship agreement <a class="header-anchor" href="#internship-agreement" aria-label="Permalink to &quot;Internship agreement&quot;">​</a></h3><p>The Coordinator enters the host company, its signing contact, the Coach-Tutor supervising the internship, the dates and the mission, editable until the first signature. On sending:</p><ul><li>the learner signs by code in their account (their legal representative through a 7-day link if they are a minor);</li><li>the company signs through a 7-day link and a code, without an account;</li><li>edPage countersigns afterwards.</li></ul><p>The jury reuses the company name in the defence decisions.</p><h2 id="electronic-signature" tabindex="-1">Electronic signature <a class="header-anchor" href="#electronic-signature" aria-label="Permalink to &quot;Electronic signature&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Mechanism</th><th>Rule</th></tr></thead><tbody><tr><td>Signature code</td><td>6 digits, sent by email, valid 15 minutes, 5 attempts, single use, stored hashed</td></tr><tr><td>Public link</td><td>Single use, valid 7 days, stored hashed, replaced by any new link</td></tr><tr><td>Sending limit</td><td>5 codes per minute per route</td></tr><tr><td>Sealing</td><td>SHA-256 fingerprint of the signed PDF, kept with the document</td></tr><tr><td>Countersignature</td><td>Automatic in the name of the edPage representative, or manual by the Coordinator according to the setting</td></tr><tr><td>Logging</td><td>Signature and countersignature timestamped, with name, email, IP and browser</td></tr></tbody></table><p>A minor never signs themselves: their legal representative receives a link separate from the consent link, and the code goes to their address.</p><h2 id="welcome-booklet-and-cohort-documents" tabindex="-1">Welcome booklet and cohort documents <a class="header-anchor" href="#welcome-booklet-and-cohort-documents" aria-label="Permalink to &quot;Welcome booklet and cohort documents&quot;">​</a></h2><ul><li>The <strong>welcome booklet</strong> is generated after full payment of the first instalment, one per agreement. It is emailed and downloadable by the learner and the Coordinator. A cohort change produces a new one; the old one is kept.</li><li>The <strong>cohort calendar</strong> lists blocks, key dates, due dates, jury days and public holidays. It is available on demand to anyone who can see the cohort.</li><li>The <strong>activity report</strong> (seats, attendance, results) is reserved for the Coordinator and the Administrator.</li><li>The <strong>defence report</strong> is produced by the person entering the jury, once each learner&#39;s defence is confirmed. It is sealed and kept; it is only regenerated if the jury decisions have been corrected, and the new one replaces the old one, which remains available.</li></ul><h2 id="document-access" tabindex="-1">Document access <a class="header-anchor" href="#document-access" aria-label="Permalink to &quot;Document access&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Actor</th><th>Sees</th></tr></thead><tbody><tr><td>Learner</td><td>Their agreements, booklet, invoices, credit notes, certificate, attestation, transcript, decision letter</td></tr><tr><td>Coordinator</td><td>The same documents from account management and the business pages</td></tr><tr><td>Funder</td><td>The tripartite agreement and the invoices for their share</td></tr><tr><td>Internship company</td><td>The internship agreement, through a link, without an account</td></tr><tr><td>Legal representative</td><td>The consents, the agreement and the internship agreement, through a link</td></tr><tr><td>Direction</td><td>Aggregated documents in the dashboards, without individual files</td></tr></tbody></table><p>Documents are available in French and English, in the recipient&#39;s language.</p><h2 id="retention" tabindex="-1">Retention <a class="header-anchor" href="#retention" aria-label="Permalink to &quot;Retention&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Document</th><th>Duration</th></tr></thead><tbody><tr><td>Agreements, invoices, credit notes</td><td>10 years (OHADA)</td></tr><tr><td>Certificates, attestations, transcripts</td><td>Unlimited</td></tr><tr><td>Defence reports</td><td>Unlimited</td></tr></tbody></table><h2 id="technical" tabindex="-1">Technical <a class="header-anchor" href="#technical" aria-label="Permalink to &quot;Technical&quot;">​</a></h2><ul><li><code>App\\Services\\Documents\\DocumentLibrary</code> lists an account&#39;s documents.</li><li><code>App\\Http\\Controllers\\Documents\\*</code> serves “My documents” and an account&#39;s documents.</li><li><code>App\\Http\\Controllers\\Cohorts\\CohortDocumentController</code> produces the calendar, activity report and defence reports.</li><li><code>App\\Concerns\\SealsPdf</code> computes and verifies fingerprints.</li><li>The PDF views live in <code>resources/views/pdf</code>, with models A and B from the appendices.</li></ul>',27)])])}const g=t(d,[["render",o]]);export{m as __pageData,g as default};
